var benchEventSelection=null,benchEventCache=null,benchEventCards=[];
function currentBenchEvents(){
 const pending=motionEnabled()&&lastEvent?.type==='goal'&&!lastEventFast&&(movementEvent!==lastEvent||movementEventAge<Movement.impactAge(lastEvent))?lastEvent:null;
 const key=state?[state.seed,state.minute,state.phase,state.subs,state.tactic,state.score.join(':'),state.logs.length,pending?.minute??'',state.lineup.map(id=>id+':'+Math.floor(state.players[id].energy)).join(',')].join('|'):'';
 if(!benchEventCache||benchEventCache.key!==key)benchEventCache={key,cards:MatchEvents.read(state,{pendingGoal:pending})};return benchEventCache.cards;
}
function renderBenchEvents(){
 if(view!=='match'||!state)return;const cards=currentBenchEvents(),button=$('match-bench-events');if(button){const active=cards.filter(c=>!['opening','watch','full'].includes(c.id)).length,text=active?'벤치 알림 '+active:'벤치 알림';if(button.textContent!==text)button.textContent=text;}
 if(matchPopupActive!=='talk')return;const host=$('bench-event-panel');if(!host)return;benchEventCards=cards;const selectedCard=cards.find(c=>c.id===benchEventSelection)||cards[0];if(!selectedCard)return;benchEventSelection=selectedCard.id;
 const p=selectedCard.identity?F.identityProfile(selectedCard.identity):null,tactic={press:'강한 압박',lowBlock:'낮은 수비',balanced:'균형 운영'}[selectedCard.tactic],labels={roster:'선발·후보 비교',tactics:'전술 직접 비교',opponent:'상대 보고서',stats:'경기 기록 보기',analysis:'기회와 체력 분석',talk:'아래 선수 대화 확인'};
 host.innerHTML='<header class="bench-event-head">'+(p?Portraits.html(p):StaffPortraits.html({name:'수석 코치'}))+'<div><small>'+state.minute+'분 · 벤치에서 온 이야기</small><h3>'+escapeText(selectedCard.title)+'</h3></div></header>'+(cards.length>1?'<label class="bench-event-picker">다른 알림 <select aria-label="벤치 알림 선택">'+cards.map(c=>'<option value="'+escapeText(c.id)+'" '+(c.id===selectedCard.id?'selected':'')+'>'+escapeText(c.title)+'</option>').join('')+'</select></label>':'')+'<p>'+escapeText(selectedCard.text)+'</p><div class="bench-event-actions">'+(selectedCard.tactic&&state.tactic!==selectedCard.tactic?'<button type="button" data-bench-tactic="'+selectedCard.tactic+'">'+tactic+' 적용</button>':'')+(selectedCard.target!=='talk'?'<button type="button" class="secondary" data-bench-target="'+selectedCard.target+'">'+labels[selectedCard.target]+'</button>':'')+'</div><small class="bench-current-plan">현재 전술: '+escapeText({press:'강한 압박',balanced:'균형 운영',counter:'빠른 역습',lowBlock:'낮은 수비'}[state.tactic]||state.tactic)+' · 변경 후에도 직접 경기 이어가기를 눌러 주세요.</small>';
 host.onchange=e=>{if(e.target.matches('select')){benchEventSelection=e.target.value;renderBenchEvents();}};
 host.onclick=e=>{const tacticButton=e.target.closest('[data-bench-tactic]'),targetButton=e.target.closest('[data-bench-target]');if(!tacticButton&&!targetButton)return;const current=currentBenchEvents().find(c=>c.id===benchEventSelection);if(!current)return;const chosen=tacticButton?.dataset.benchTactic;if(chosen&&chosen===current.tactic){action(()=>{pauseForPlanning();F.setTactic(state,chosen);});renderBenchEvents();$('bench-event-panel').querySelector('h3')?.focus({preventScroll:true});}else if(targetButton&&targetButton.dataset.benchTarget===current.target){if(current.playerId&&state.lineup.includes(current.playerId))selected=current.playerId;openMatchPopup(current.target,button);}};
 host.querySelector('h3').tabIndex=-1;
}
const benchEventPanel=document.createElement('section');benchEventPanel.id='bench-event-panel';$('match-popup-talk').prepend(benchEventPanel);
const benchOriginalPopup=renderMatchPopup;renderMatchPopup=function(){benchOriginalPopup();renderBenchEvents();};
